data: {"index":1,"delta":{"text":" focuses almost exclusively on human readability, minimizing boilerplate code to let developers focus on problem-solving.\n\n### JavaScript: Ubiquity","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" and Flexibility\nCreated by Brendan Eich in 1995 for Netscape, JavaScript was designed to bring interactivity to the","type":"text"},"event_type":"step.delta"}

